            reject: [{ re: 'no value|wrong|useless|false', hint: 'A limit makes the point smaller, not useless. Keep your position.' },
              { re: '^(because|although|though|but)\\b', hint: 'These words show a result, so the linker shows a result.' },
              { re: 'has it limits', hint: 'Check the word before "limits".' }],
